def solve():
    pp = P["PURCHASE_PRICE"]
    claims = [P["CLAIM_A"], P["CLAIM_B"], P["CLAIM_C"]]
    dm = P["DE_MINIMIS"]
    basket = P["BASKET"]
    cap_pct = P["CAP_PCT"]
    bt = P["BASKET_TYPE"]
    if bt not in ("deductible", "tipping"):
        raise ValueError("unknown basket type")
    eligible = 0
    for c in claims:
        if c >= dm:
            eligible = eligible + c
    if eligible > basket:
        if bt == "deductible":
            before_cap = eligible - basket
        else:
            before_cap = eligible
    else:
        before_cap = 0
    cap_amount = pp * cap_pct / 100
    if before_cap > cap_amount:
        final = cap_amount
    else:
        final = before_cap
    return {
        "final": final,
        "eligible_claims_total": eligible,
        "recoverable_before_cap": before_cap,
        "cap_amount": cap_amount,
    }
